Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;

const int MAXC = 400;
int cap[MAXC][MAXC];
char scien[20][20], reac[20][20];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};
int n, t;
int shortest[15][15][15][15];
int reach[13][13], treach[13][13];

int getnode(int x, int y) {
    return (x - 1) * n + y - 1;
}

void expand(int val) {
    memcpy(treach, reach, sizeof(reach));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (treach[i][j] == val) {
                for (int k = 0; k < 4; k++) {
                    int ni = i + dx[k];
                    int nj = j + dy[k];
                    if (ni > 0 && nj > 0 && ni <= n && nj <= n && treach[ni][nj] < val && scien[ni][nj] != 'Y') {
                        reach[ni][nj] = val;
                    }
                }
            }
        }
    }
}

bool canreach(int sx, int sy, int tx, int ty, int ix, int iy) {
    memset(reach, 0, sizeof(reach));
    reach[sx][sy] = 1;
    reach[ix][iy] = 2;
    int iters = 100;
    while (iters--) {
        expand(1);
        if (reach[tx][ty] == 1) return true;
        expand(2);
        if (reach[tx][ty] == 2) return false;
    }
    return false;
}

bool bfs(int src, int sink, int parent[]) {
    memset(parent, -1, MAXC * sizeof(int));
    queue<int> q;
    q.push(src);
    parent[src] = src;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v = 0; v <= sink; v++) {
            if (parent[v] == -1 && cap[u][v] > 0) {
                parent[v] = u;
                if (v == sink) return true;
                q.push(v);
            }
        }
    }
    return false;
}

int main() {
    memset(shortest, 1, sizeof(shortest));
    cin >> n >> t;
    int infx = 0, infy = 0;
    for (int i = 1; i <= n; i++) {
        cin >> (scien[i] + 1);
        for (int j = 1; j <= n; j++) {
            shortest[i][j][i][j] = 0;
            if (scien[i][j] == 'Z') {
                infx = i;
                infy = j;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cin >> (reac[i] + 1);
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            for (int k = 0; k < 4; k++) {
                int ni = i + dx[k];
                int nj = j + dy[k];
                if (ni > 0 && ni <= n && nj > 0 && nj <= n && scien[i][j] != 'Y' && scien[ni][nj] != 'Y') {
                    shortest[i][j][ni][nj] = 1;
                }
            }
        }
    }
    for (int kx = 1; kx <= n; kx++) {
        for (int ky = 1; ky <= n; ky++) {
            for (int sx = 1; sx <= n; sx++) {
                for (int sy = 1; sy <= n; sy++) {
                    for (int tx = 1; tx <= n; tx++) {
                        for (int ty = 1; ty <= n; ty++) {
                            shortest[sx][sy][tx][ty] = min(shortest[sx][sy][tx][ty],
                                                           shortest[sx][sy][kx][ky] + shortest[kx][ky][tx][ty]);
                        }
                    }
                }
            }
        }
    }
    int src = n * n * 2 + 1;
    int sink = n * n * 2 + 2;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (isdigit(scien[i][j])) {
                cap[src][getnode(i, j)] = scien[i][j] - '0';
            }
            if (isdigit(reac[i][j])) {
                cap[n * n + getnode(i, j)][sink] = reac[i][j] - '0';
            }
            if (isdigit(scien[i][j])) {
                for (int a = 1; a <= n; a++) {
                    for (int b = 1; b <= n; b++) {
                        if (scien[i][j] > '0' && reac[a][b] > '0' && isdigit(reac[a][b]) &&
                            shortest[i][j][a][b] <= t && canreach(i, j, a, b, infx, infy)) {
                            cap[getnode(i, j)][n * n + getnode(a, b)] = 1000;
                        }
                    }
                }
            }
        }
    }
    int flow = 0;
    int parent[MAXC];
    while (bfs(src, sink, parent)) {
        int bottleneck = 1000000000;
        for (int v = sink; v != src; v = parent[v]) {
            int u = parent[v];
            bottleneck = min(bottleneck, cap[u][v]);
        }
        for (int v = sink; v != src; v = parent[v]) {
            int u = parent[v];
            cap[u][v] -= bottleneck;
            cap[v][u] += bottleneck;
        }
        flow += bottleneck;
    }
    cout << flow << '\n';
    return 0;
}
